// Vercel serverless function: sends a branded, designed invoice email with
// payment links (Venmo, CashApp, PayPal, Zelle, Apple Cash) via Resend.
// Called by moneytracker/index.html's "Send Invoice" button.
//
// Env vars required (set in Vercel project settings):
//   RESEND_API_KEY      — Resend API key
//   INVOICE_FROM        — sending address, e.g. "Bryson Hunter <billing@brysonhunter.com>"
//
// Also writes a row to mt_invoices (Supabase) so the send is logged in the debtor's history.

const SB_URL = 'https://udirnxilxlvhkzbgpjke.supabase.co';
const SB_KEY = 'sb_publishable_7SGeCmx1XATdHTawyT6hHw_iWV9-1Vz';

const SITE_URL = 'https://brysonhunter.com';

// Bryson Hunter Enterprises logo, dark-background variant (from Obsidian brand vault:
// Brand Kit/01b — Personal Logos/Dark_Bryson_hunter_enterprises_logo.jpg). Embedded as a
// base64 data URI so it always renders regardless of the recipient's "load remote images" setting.
const LOGO_DATA_URI = 'data:image/jpeg;base64,';

const PAY_LINKS = {
  venmo: 'https://www.venmo.com/u/bhunt2388',
  cashapp: 'https://cash.app/$bhunt23',
  paypal: 'https://paypal.me/BrysonHunter801',
  zelleTag: 'Brysonhunter', // Zelle has no universal deep link — shown as a tag to search for in your banking app
  applecashNumber: '8014002916', // Apple Cash is P2P via Messages/Contacts only — shown as a number, not a link
};

function fmt(n) {
  return '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function buildInvoiceHtml({ debtorName, amount, dueNote }) {
  const amountStr = fmt(amount);
  const safeDebtorName = escapeHtml(debtorName);
  const safeDueNote = dueNote ? escapeHtml(dueNote) : '';

  return `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
</head>
<body style="margin:0; padding:0; background:#0e0d0b; font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#0e0d0b; padding:40px 16px;">
    <tr>
      <td align="center">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px; background:#1c1a15; border:1px solid #2f2a22; border-radius:16px; overflow:hidden;">

          <!-- Brand header -->
          <tr>
            <td style="padding:32px 32px 20px; text-align:center; border-bottom:1px solid #2f2a22;">
              <img src="${LOGO_DATA_URI}" alt="Bryson Hunter Enterprises" width="88" style="display:block; margin:0 auto 14px; border-radius:8px;" />
              <a href="${SITE_URL}" style="color:#c9a961; font-size:12px; text-decoration:none; letter-spacing:.5px;">brysonhunter.com</a>
            </td>
          </tr>

          <tr>
            <td style="padding:28px 32px 8px;">
              <div style="color:#756d5b; font-size:12px; text-transform:uppercase; letter-spacing:1px; margin-bottom:6px;">Invoice</div>
              <div style="color:#f2ede2; font-size:22px; font-weight:700; margin-bottom:22px;">Payment Requested</div>

              <div style="color:#756d5b; font-size:13px; margin-bottom:4px;">Billed to</div>
              <div style="color:#f2ede2; font-size:17px; font-weight:600; margin-bottom:20px;">${safeDebtorName}</div>

              <div style="color:#756d5b; font-size:13px; margin-bottom:4px;">Amount Due</div>
              <div style="color:#c9a961; font-size:34px; font-weight:800; margin-bottom:${safeDueNote ? '10px' : '24px'};">${amountStr}</div>
              ${safeDueNote ? `<div style="color:#756d5b; font-size:13px; font-style:italic; margin-bottom:24px;">${safeDueNote}</div>` : ''}

              <div style="color:#756d5b; font-size:13px; text-transform:uppercase; letter-spacing:.5px; margin-bottom:14px;">Pay With</div>

              <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
                <tr>
                  <td style="padding-bottom:10px;">
                    <a href="${PAY_LINKS.venmo}" style="display:block; text-align:center; background:#3D95CE; color:#ffffff; text-decoration:none; font-weight:700; font-size:15px; padding:14px; border-radius:10px;">Pay with Venmo</a>
                  </td>
                </tr>
                <tr>
                  <td style="padding-bottom:10px;">
                    <a href="${PAY_LINKS.cashapp}" style="display:block; text-align:center; background:#00D632; color:#04310f; text-decoration:none; font-weight:700; font-size:15px; padding:14px; border-radius:10px;">Pay with Cash App</a>
                  </td>
                </tr>
                <tr>
                  <td style="padding-bottom:10px;">
                    <a href="${PAY_LINKS.paypal}" style="display:block; text-align:center; background:#0070BA; color:#ffffff; text-decoration:none; font-weight:700; font-size:15px; padding:14px; border-radius:10px;">Pay with PayPal</a>
                  </td>
                </tr>
                <tr>
                  <td style="padding-bottom:10px;">
                    <div style="background:#6D1ED4; color:#ffffff; text-align:center; font-weight:700; font-size:15px; padding:14px; border-radius:10px;">
                      Zelle — search <span style="text-decoration:underline;">${PAY_LINKS.zelleTag}</span> in your bank app
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div style="background:#000000; color:#ffffff; text-align:center; font-weight:700; font-size:15px; padding:14px; border-radius:10px; border:1px solid #333;">
                       Apple Cash — send to ${PAY_LINKS.applecashNumber}
                    </div>
                  </td>
                </tr>
              </table>

              <div style="color:#756d5b; font-size:11.5px; margin-top:14px; line-height:1.5;">
                Zelle and Apple Cash don't support clickable payment links from email — open your banking app or Messages and use the info above.
              </div>
            </td>
          </tr>
          <tr>
            <td style="padding:22px 32px; background:#161410; text-align:center; border-top:1px solid #2f2a22;">
              <div style="color:#b4ab97; font-size:12px; font-weight:600; margin-bottom:2px;">Bryson Hunter Enterprises</div>
              <div style="color:#756d5b; font-size:11px;"><a href="${SITE_URL}" style="color:#756d5b; text-decoration:none;">brysonhunter.com</a> · Sent via Money Tracker</div>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`.trim();
}

async function sbInsert(table, row) {
  const res = await fetch(`${SB_URL}/rest/v1/${table}`, {
    method: 'POST',
    headers: {
      apikey: SB_KEY,
      Authorization: `Bearer ${SB_KEY}`,
      'Content-Type': 'application/json',
      Prefer: 'return=minimal',
    },
    body: JSON.stringify(row),
  });
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(`Supabase insert failed: ${res.status} ${text}`);
  }
}

export default async function handler(req, res) {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  let body = req.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  body = body || {};

  const { debtId, debtorName, amount, toEmail, dueNote } = body;

  if (!debtId || !debtorName || !amount || !toEmail) {
    res.status(400).json({ error: 'Missing required fields: debtId, debtorName, amount, toEmail' });
    return;
  }

  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) {
    res.status(500).json({ error: 'RESEND_API_KEY not configured on the server yet.' });
    return;
  }

  const from = process.env.INVOICE_FROM || 'Bryson Hunter <billing@brysonhunter.com>';
  const html = buildInvoiceHtml({ debtorName, amount, dueNote });

  try {
    const sendResp = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        from,
        to: [toEmail],
        subject: `Invoice — ${fmt(amount)} due`,
        html,
      }),
    });

    const sendJson = await sendResp.json().catch(() => ({}));

    if (!sendResp.ok) {
      res.status(502).json({ error: 'Resend send failed', detail: sendJson });
      return;
    }

    // Log the invoice send to Supabase (best-effort — don't fail the response if this errors)
    try {
      await sbInsert('mt_invoices', {
        id: 'inv-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
        debt_id: debtId,
        amount,
        to_email: toEmail,
        status: 'sent',
        resend_id: sendJson.id || null,
      });
    } catch (logErr) {
      console.error('[send-invoice] failed to log invoice to Supabase:', logErr);
    }

    res.status(200).json({ status: 'sent', resendId: sendJson.id || null });
  } catch (err) {
    console.error('[send-invoice] error:', err);
    res.status(500).json({ error: String(err) });
  }
}
